namespace Atm.Tests;

/// <summary>Enveloppe le vrai module, enregistre les appels et peut simuler une panne.</summary>
internal sealed class RecordingDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    private readonly MoneyDispenser _inner = new(stock, jammed);

    public List<NoteCounts> DispenseCalls { get; } = [];
    public List<NoteCounts> LoadCalls { get; } = [];

    /// <summary>Numéro (à partir de 1) de l'appel à <c>Dispense</c> qui échoue, ou <c>null</c>.</summary>
    public int? FailDispenseOnCall { get; init; }

    public bool FailLoad { get; init; }

    public NoteCounts Stock => _inner.Stock;

    public Denomination? Jammed => _inner.Jammed;

    public bool Dispense(NoteCounts notes)
    {
        DispenseCalls.Add(notes);
        return DispenseCalls.Count != FailDispenseOnCall && _inner.Dispense(notes);
    }

    public bool Load(NoteCounts notes)
    {
        LoadCalls.Add(notes);
        return !FailLoad && _inner.Load(notes);
    }
}

internal sealed record UnknownOperation : Operation;
namespace Atm.Tests;

/// <summary>Tests ajoutés pour tuer les mutants qui survivaient à la suite existante.</summary>
public class Renforts
{
    [Fact]
    public void Unknown_operation_error_names_the_operation_type()
    {
        var machine = new CashMachine(new MoneyDispenser(NoteCounts.None));

        var error = Assert.Throws<ArgumentException>(() => machine.Execute(default, new UnknownOperation()));

        Assert.Equal("operation", error.ParamName);
        Assert.Contains(nameof(UnknownOperation), error.Message);
    }
}
namespace Atm.Tests;

public class CashMachineTests
{
    private static Denomination? Jam(int jammed) => jammed == 0 ? null : (Denomination)jammed;

    private static (AtmResult Result, MoneyDispenser Dispenser) Run(
        int balance, int withdrawn, NoteCounts stock, Denomination? jammed, Operation operation)
    {
        var dispenser = new MoneyDispenser(stock, jammed);
        var result = new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), operation);
        return (result, dispenser);
    }

    private static void AssertRefused(AtmResult result, AtmStatus status, AccountState account)
    {
        Assert.Equal(status, result.Status);
        Assert.Equal(NoteCounts.None, result.Notes);
        Assert.Equal(0, result.Fee);
        Assert.Equal(account, result.Account);
    }

    // ---------- Exemples de la spécification ----------

    [Theory]
    // solde, retiré, stock 50/20/10, bloquée, montant, billets attendus 50/20/10, frais, solde après, retiré après
    [InlineData(100, 0, 1, 3, 0, 0, 60, 0, 3, 0, 0, 40, 60)]
    [InlineData(100, 0, 1, 1, 1, 0, 80, 1, 1, 1, 0, 20, 80)]
    [InlineData(105, 0, 5, 5, 5, 0, 100, 2, 0, 0, 0, 5, 100)]
    [InlineData(115, 0, 5, 5, 5, 0, 110, 2, 0, 1, 5, 0, 110)]
    [InlineData(250, 0, 2, 2, 0, 50, 40, 0, 2, 0, 0, 210, 40)]
    public void Withdraw_examples_succeed(
        int balance, int withdrawn, int f, int t, int c, int jammed, int amount,
        int ef, int et, int ec, int fee, int balanceAfter, int withdrawnAfter)
    {
        var stock = new NoteCounts(f, t, c);
        var (result, dispenser) = Run(balance, withdrawn, stock, Jam(jammed), new Operation.Withdraw(amount));

        var expected = new NoteCounts(ef, et, ec);
        Assert.Equal(AtmStatus.Ok, result.Status);
        Assert.Equal(expected, result.Notes);
        Assert.Equal(fee, result.Fee);
        Assert.Equal(new AccountState(balanceAfter, withdrawnAfter), result.Account);
        Assert.Equal(stock - expected, dispenser.Stock);
    }

    [Theory]
    [InlineData(110, 0, 5, 5, 5, 0, 110, AtmStatus.InsufficientFunds)]
    [InlineData(250, 150, 5, 5, 5, 0, 60, AtmStatus.DailyLimitExceeded)]
    [InlineData(250, 0, 1, 0, 0, 50, 50, AtmStatus.CannotDispense)]
    [InlineData(0, 200, 0, 0, 0, 0, 5, AtmStatus.InvalidAmount)]
    public void Withdraw_examples_are_refused(
        int balance, int withdrawn, int f, int t, int c, int jammed, int amount, AtmStatus status)
    {
        var stock = new NoteCounts(f, t, c);
        var (result, dispenser) = Run(balance, withdrawn, stock, Jam(jammed), new Operation.Withdraw(amount));

        AssertRefused(result, status, new AccountState(balance, withdrawn));
        Assert.Equal(stock, dispenser.Stock);
    }

    [Fact]
    public void Deposit_example_into_full_cassette_is_refused()
    {
        var stock = new NoteCounts(0, 5, 0);
        var (result, dispenser) = Run(10, 0, stock, null, new Operation.Deposit(new NoteCounts(0, 1, 0)));

        AssertRefused(result, AtmStatus.CassetteFull, new AccountState(10, 0));
        Assert.Equal(stock, dispenser.Stock);
    }

    [Fact]
    public void Deposit_example_into_jammed_cassette_is_refused()
    {
        var stock = new NoteCounts(0, 1, 0);
        var (result, dispenser) = Run(10, 30, stock, Denomination.Twenty, new Operation.Deposit(new NoteCounts(0, 1, 0)));

        AssertRefused(result, AtmStatus.CassetteJammed, new AccountState(10, 30));
        Assert.Equal(stock, dispenser.Stock);
    }
namespace Atm.Tests;

/// <summary>Parcourt une large part du domaine et compare à un modèle de référence écrit indépendamment.</summary>
public class DomainSweepTests
{
    private static readonly Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];

    private static IEnumerable<NoteCounts> AllStocks()
    {
        for (var f = 0; f <= 5; f++)
            for (var t = 0; t <= 5; t++)
                for (var c = 0; c <= 5; c++)
                    yield return new NoteCounts(f, t, c);
    }

    private static AtmResult ExpectedWithdraw(AccountState a, NoteCounts stock, Denomination? jam, int amount)
    {
        AtmResult Refused(AtmStatus s) => new(s, NoteCounts.None, 0, a);

        if (amount <= 0 || amount % 10 != 0) return Refused(AtmStatus.InvalidAmount);
        if (a.WithdrawnToday + amount > 200) return Refused(AtmStatus.DailyLimitExceeded);
        var fee = amount > 100 ? 5 : 0;
        if (amount + fee > a.Balance) return Refused(AtmStatus.InsufficientFunds);

        var usable = new NoteCounts(
            jam == Denomination.Fifty ? 0 : stock.Fifties,
            jam == Denomination.Twenty ? 0 : stock.Twenties,
            jam == Denomination.Ten ? 0 : stock.Tens);

        var candidates = (
            from f in Enumerable.Range(0, usable.Fifties + 1)
            from t in Enumerable.Range(0, usable.Twenties + 1)
            from c in Enumerable.Range(0, usable.Tens + 1)
